package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The number a claim being opened takes: the sheet's next (1, 2, ...), or, while the sheet's period
 * numbering from is set and its today is on or after it, the next within the claim's period (the one containing its due-by)
 * (<period name>-<n>), or X-<n> when the claim is in no period.
 */
public final class ClaimNumbers {
    private ClaimNumbers() {}

    public static String next(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods, ClaimRepository claims) {
        if (!settings.numbersByPeriod(sheet.today())) return String.valueOf(claims.nextNumber(sheet.id()));
        Period period = periods.findAll(sheet.id()).stream()
                .filter((p) -> p.contains(claim.getDueBy())).findFirst().orElse(null);
        if (period == null) return "X-" + claims.nextNumberIn(sheet.id(), "");
        return period.name() + "-" + claims.nextNumberIn(sheet.id(), period.name());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Gives a claim being opened its number (the sheet's next, or the next within its period); refused
 * when another request opened it first.
 */
public class NumberClaim {
    public void number(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository, SettingsRepository settings,
            PeriodRepository periods) throws InvalidClaimStatusException {
        if (!repository.markOpened(claim)) throw new InvalidClaimStatusException(ClaimStatus.DRAFT, ClaimStatus.OPEN);
        claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, repository));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Gives a claim moved to another person the next number in the sequence it would be numbered in
 * (the sheet's, or its period's); its old number is never used again. A draft has none and gets none.
 */
public class RenumberClaim {
    public void renumber(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository, SettingsRepository settings,
            PeriodRepository periods) {
        give(sheet, claim, repository, settings, periods);
    }

    static void give(Sheet sheet, Claim claim, ClaimRepository repository, SettingsRepository settings,
            PeriodRepository periods) {
        if (claim.getNumber() == null) return;
        claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, repository));
    }
}
package net.officefloor.hq.app.sheet;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The sheet's descendants: the sheets naming it as their parent, the sheets naming those, and so
 * on. Each is listed once, and never the sheet itself.
 */
public class RespondWithDescendants {
    public void respond(@Val Sheet sheet, SheetRepository repository, ObjectResponse<DescendantsResponse> response) {
        List<String> descendants = new ArrayList<>();
        Set<String> seen = new HashSet<>(Set.of(sheet.id()));
        Deque<String> pending = new ArrayDeque<>(List.of(sheet.id()));
        while (!pending.isEmpty()) {
            for (String child : repository.children(pending.removeFirst())) {
                if (seen.add(child)) {
                    descendants.add(child);
                    pending.addLast(child);
                }
            }
        }
        response.send(new DescendantsResponse(descendants));
    }
}
